package plates.countries.iran

import plates.core.validators.PlateCheck
import plates.core.validators.RuledPlateValidator

/** Judges a temporary plate's expiry: year 00-99 over month 1-12. Quiet on plates without a month. Reports, never bars a keystroke. */
class IranTemporaryValidator : RuledPlateValidator("month") {
    override val checks = listOf(
        PlateCheck("year", "[0-9]{2}", "The year is 2 digits, 00 to 99."),
        PlateCheck("month", "0?[1-9]|1[0-2]", "The month is 1 to 12."),
    )
}
